244		if err != nil {
245			t.Fatalf("被拒绝的请求编号应仍可合法使用: %v", err)
246		}
247		if f.Seq != 2 || f.Grams != "1" {
248			t.Fatalf("新投料结果不正确: %+v", f)
249		}
