37	
38	// 首次使用空位置：台账为空，查询返回未找到。
39	func TestOpenEmptyAndNotFound(t *testing.T) {
40		s := openTestStore(t)
41		if _, err := s.GetBatch("B1"); !errors.Is(err, ErrNotFound) {
42			t.Fatalf("查询不存在的批次应返回 ErrNotFound，得到 %v", err)
43		}
44		if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrNotFound) {
45			t.Fatalf("查询不存在的配方应返回 ErrNotFound，得到 %v", err)
46		}
47	}
48	
49	// 空位置关闭后重新打开，仍然为空台账。
50	func TestReopenEmptyLocation(t *testing.T) {
51		dir := t.TempDir()
52		s1, err := Open(dir)
53		if err != nil {
54			t.Fatal(err)
