1	package release
2	
3	import (
4		"errors"
5		"fmt"
6		"math"
7		"regexp"
8		"strconv"
9		"strings"
10	)
11	
12	// gramsMilli 以千分之一克为单位定点存储克数，避免浮点误差。
13	type gramsMilli int64
14	
15	// maxGramsMilli 是同一批次内每种物料累计实投的上限，
16	// 即 9223372036854775.807 克（math.MaxInt64 个千分之一克）。
17	const maxGramsMilli gramsMilli = math.MaxInt64
18	
19	// feedingAccumulator 按物料累计一个批次内的实投量（千分之一克）。
20	// 追加投料、读取台账校验与批次数量核对共用这一套数量规则：
21	// 累计范围始终是一个批次中的一种物料，其他物料与其他批次的数量
22	// 不参与，物料之间也不互相抵消；任一物料的累计上限为 maxGramsMilli，
23	// 恰好达到上限合法，再增加 0.001 克即判超限。累计不回绕、不截断、
24	// 不舍入，精确到千分之一克。
25	type feedingAccumulator struct {
26		sums map[string]gramsMilli
27	}
28	
29	func newFeedingAccumulator() *feedingAccumulator {
30		return &feedingAccumulator{sums: map[string]gramsMilli{}}
31	}
32	
33	// add 计入一条该物料的投料；计入后会超过上限时返回 false 且不计入，
34	// 已有累计保持不变。
35	func (a *feedingAccumulator) add(materialNo string, g gramsMilli) bool {
36		sum := a.sums[materialNo]
37		if g > maxGramsMilli-sum {
38			return false
39		}
40		a.sums[materialNo] = sum + g
41		return true
42	}
43	
44	// total 返回该物料的累计实投量；无投料记录时为零。
45	func (a *feedingAccumulator) total(materialNo string) gramsMilli {
46		return a.sums[materialNo]
47	}
48	
49	var gramsPattern = regexp.MustCompile(`^(\d+)(?:\.(\d{1,3}))?$`)
50	
51	// parseGrams 将克数字符串精确解析为千分之一克。
52	// 规则：必须为正数，且最多三位小数（如 100、100.5、0.001 合法；0、-1、1.2345 非法）。
53	func parseGrams(s string) (gramsMilli, error) {
54		s = strings.TrimSpace(s)
55		if s == "" {
56			return 0, errors.New("克数不能为空")
57		}
58		m := gramsPattern.FindStringSubmatch(s)
59		if m == nil {
60			return 0, fmt.Errorf("克数 %q 不合法：必须为正数且最多三位小数", s)
61		}
62		whole, err := strconv.ParseInt(m[1], 10, 64)
63		if err != nil {
64			return 0, fmt.Errorf("克数 %q 不合法", s)
65		}
66		var frac int64
67		if m[2] != "" {
68			f := m[2]
69			for len(f) < 3 {
70				f += "0"
71			}
72			frac, err = strconv.ParseInt(f, 10, 64)
73			if err != nil {
74				return 0, fmt.Errorf("克数 %q 不合法", s)
75			}
76		}
77		// 先做溢出检查，避免整数回绕把超大克数变成较小的值。
78		if whole > int64(maxGramsMilli)/1000 ||
79			(whole == int64(maxGramsMilli)/1000 && frac > int64(maxGramsMilli)%1000) {
80			return 0, fmt.Errorf("克数 %q 超出范围：单次数量不能超过 %s 克", s, maxGramsMilli)
81		}
82		milli := whole*1000 + frac
83		if milli <= 0 {
84			return 0, fmt.Errorf("克数 %q 必须为正数", s)
85		}
86		return gramsMilli(milli), nil
87	}
88	
89	// String 将千分之一克格式化为克数字符串，去掉末尾多余的 0。
90	func (g gramsMilli) String() string {
91		sign := ""
92		v := int64(g)
93		if v < 0 {
94			sign = "-"
95			v = -v
96		}
97		w, f := v/1000, v%1000
98		if f == 0 {
99			return sign + strconv.FormatInt(w, 10)
100		}
101		fs := strings.TrimRight(fmt.Sprintf("%03d", f), "0")
102		return sign + strconv.FormatInt(w, 10) + "." + fs
103	}
104	
105	// multiplyPortions 将每份克数与计划份数相乘，计算某物料的应投量
106	// （每份克数 × 计划份数）。它是数量规则 planRequirements 使用的底层
107	// 定点运算，创建批次、调整草稿、读取校验与批次数量核对最终都经由
